"""Walks generated by NVIDIA's own Kimodo pipeline (github.com/nv-tlabs/kimodo), for comparing with ours.

Uses the official package's loader, generation call and G1 MuJoCo export on the same
``Kimodo-G1-RP-v1`` weights, with the official defaults: the whole clip at once from text only,
separated guidance at the checkpoint's defaults, 100 DDIM steps, the generation script's
multi-prompt path with 5 transition frames, and no post-processing (the official script turns it
off for G1). The one substitution: the text encoder is a stand-in returning phrase embeddings
already computed with the same LLM2Vec encoder (its Llama base needs gated access), passed through
the loader's ``text_encoder`` argument.

Each clip is written as a segment file (``demo_walks``) for gait numbers and SONIC replay; the
window skips the first second (the start from rest).

``--variant`` swaps one official setting for our wrapper's, to find which one spoils the gait
(single-segment generation, the official path for constrained generation):

  single              the official setting through the single-segment path (the base for the rest)
  steps-50            50 DDIM steps instead of 100
  path-text           text, plus the root ground path and heading on every frame (0.35 m/s, 1 m/s^2 start)
  path-notext         the same path, text guidance weight 0 (our default conditioning and guidance)
  short               only 50 frames (1.67 s) from scratch, measured whole
  history             100 frames of an official clip (same seed) as full-body constraints, 50 free frames after
  history-path-notext the history, plus the path on the 50 free frames and text weight 0 (one plan of our wrapper)

    python official_kimodo.py --kimodo-src <nv-tlabs/kimodo checkout> --checkpoint-dir <dir holding Kimodo-G1-RP-v1> \\
        --text-cache <phrase embeddings> --out <segments dir> [--seconds 8] [--seeds 1000 ...]
"""
import argparse
import json
import os
import sys
import time
from pathlib import Path

import numpy as np
import torch

sys.path.insert(0, str(Path(__file__).resolve().parents[2]/'scripts'))  # agentic/scripts: paths.py
import paths  # noqa: F401  (puts this checkout's package first)
from kimodo_vla.oracle import demo_walks as dw

PROMPTS = {'forward': ('walk_forward', 'A person walks forward.'),
           'backward': ('walk_backward', 'A person walks backward.'),
           'left': ('sidestep_left', 'A person side steps to the left.'),
           'right': ('sidestep_right', 'A person side steps to the right.'),
           'turn': ('turn_left_in_place', 'A person turns to the left in place.')}


class CachedText:
    """Stands in for the official LLM2Vec encoder: returns a precomputed embedding for each prompt."""
    def __init__(self, cache_dir):
        self.table = {}
        for path in Path(cache_dir).glob('*.pt'):
            payload = torch.load(path, map_location='cpu', weights_only=True)
            self.table[payload['instruction'].strip()] = torch.as_tensor(payload['embedding']).float()

    def to(self, *args, **kwargs):
        return self

    def eval(self):
        return self

    def __call__(self, texts):
        single = isinstance(texts, str)
        texts = [texts] if single else texts
        missing = [t for t in texts if t.strip() and t.strip() not in self.table]
        if missing:
            raise KeyError(f'No cached embedding for {missing}')
        # [B, 1, 4096] and one token each, as the official LLM2Vec wrapper returns
        feat = torch.cat([self.table[t.strip()] if t.strip() else torch.zeros(1, 4096) for t in texts])[:, None]
        lengths = [1]*len(texts)
        return (feat[0], lengths[0]) if single else (feat, lengths)


def qpos_to_actions(qpos, fps):
    """Official MuJoCo qpos rows (root xyz, quaternion wxyz, 29 joints in the XML's order) -> actions at 50 Hz."""
    q = np.asarray(qpos, dtype=float)
    rows = np.concatenate([q[:, :3], q[:, [4, 5, 6, 3]], q[:, 7:]], axis=1)  # quaternion to xyzw, as LAFAN1 rows
    return dw.lafan1_actions(rows, fps=fps)


def compare_port(args, model):
    """Official ``_generate`` vs ``kimodo_vla.model.segment_sampler.sample_segment`` from the same noise."""
    from kimodo.constraints import Root2DConstraintSet
    from kimodo_vla.model.native_policy import NativeKimodoPolicy
    from kimodo_vla.model.segment_sampler import sample_segment
    ours = NativeKimodoPolicy(Path(args.checkpoint_dir)/'Kimodo-G1-RP-v1').to('cuda').eval()
    text = CachedText(args.text_cache)
    frames, rows = int(args.seconds*model.fps), []
    for direction in args.directions:
        if direction == 'turn':
            continue
        key, prompt = PROMPTS[direction]
        for seed in args.seeds[:2]:
            for case in ('text', 'path-notext'):
                observed = mask = None
                cfg = [2., 2.]
                if case == 'path-notext':
                    unit = {'forward': (0., 1.), 'backward': (0., -1.), 'left': (1., 0.), 'right': (-1., 0.)}[direction]
                    xz = torch.tensor(np.outer(.35*np.arange(frames)/model.fps, unit), dtype=torch.float32, device='cuda')
                    c = Root2DConstraintSet(model.skeleton, torch.arange(frames, device='cuda'), xz,
                                            global_root_heading=torch.tensor(np.tile([1., 0.], (frames, 1)), dtype=torch.float32, device='cuda'))
                    observed, mask = model.motion_rep.create_conditions_from_constraints_batched(
                        [c], torch.tensor([frames], device='cuda'), to_normalize=True, device='cuda')
                    cfg = [0., 2.]
                torch.manual_seed(seed)
                theirs = model._generate([prompt], frames, num_denoising_steps=args.steps,
                                         pad_mask=torch.ones(1, frames, dtype=torch.bool, device='cuda'),
                                         first_heading_angle=torch.zeros(1, device='cuda'), motion_mask=mask,
                                         observed_motion=observed, cfg_weight=cfg, progress_bar=lambda x: x)
                if mask is None:
                    values, m = torch.zeros(frames, ours.representation.motion_rep_dim), torch.zeros(frames, ours.representation.motion_rep_dim, dtype=torch.bool)
                else:
                    m = mask[0].bool().cpu()
                    values = ours.representation.unnormalize(observed[0].float()).cpu().masked_fill(~m, 0)
                torch.manual_seed(seed)
                feats, _ = sample_segment(ours, values, m, first_heading=0., text_feat=text.table[prompt] if case == 'text' else None,
                                          text_weight=cfg[0], constraint_weight=cfg[1], steps=args.steps)
                mine = ours.representation.normalize(feats.to('cuda')[None])
                diff = float((mine-theirs.float()).abs().max())
                rows.append({'direction': direction, 'seed': seed, 'case': case, 'max_abs_diff_normalized': diff})
                print(direction, seed, case, f'max |official - ours| (normalized features) = {diff:.2e}', flush=True)
    print(json.dumps(rows))


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--kimodo-src', required=True)
    p.add_argument('--checkpoint-dir', required=True)
    p.add_argument('--text-cache', required=True)
    p.add_argument('--out', required=True)
    p.add_argument('--seconds', type=float, default=8.)
    p.add_argument('--seeds', type=int, nargs='+', default=[1000, 1001, 1002, 1003, 1004])
    p.add_argument('--steps', type=int, default=100, help='DDIM steps (the official script\'s default is 100)')
    p.add_argument('--directions', nargs='+', default=list(PROMPTS))
    p.add_argument('--compare-port', action='store_true',
                   help='instead: check that kimodo_vla.model.segment_sampler reproduces the official sampler (same seed)')
    p.add_argument('--variant', default='official', choices=['official', 'single', 'steps-50', 'path-text', 'path-notext',
                                                               'short', 'history', 'history-path-notext'])
    args = p.parse_args()
    sys.path.insert(0, str(Path(args.kimodo_src).resolve()))
    os.environ['CHECKPOINT_DIR'] = str(Path(args.checkpoint_dir).resolve())
    os.environ['LOCAL_CACHE'] = 'True'
    from kimodo import load_model
    from kimodo.exports.mujoco import MujocoQposConverter
    from kimodo.tools import seed_everything
    from kimodo.constraints import FullBodyConstraintSet, Root2DConstraintSet
    model, name = load_model('Kimodo-G1-RP-v1', device='cuda', text_encoder=CachedText(args.text_cache),
                             return_resolved_name=True)
    converter = MujocoQposConverter(model.skeleton)
    names = [j.get('name') for j in __import__('xml.etree.ElementTree', fromlist=['x']).parse(converter.xml_path).iter('joint')
             if j.get('name') and j.get('type', 'hinge') == 'hinge']
    if tuple(names) != dw.LAFAN1_G1_JOINTS:
        raise SystemExit(f'Unexpected joint order in {converter.xml_path}: {names}')
    if args.compare_port:
        return compare_port(args, model)
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=False)
    frames = int(args.seconds*model.fps)
    fk = dw.g1_fk()
    rows = []
    v = args.variant
    steps = 50 if v == 'steps-50' else args.steps

    def path(n, direction, speed=.35, accel=1.):
        """Root ground path (kimodo x left, z forward) and constant heading for n frames."""
        unit = {'forward': (0., 1.), 'backward': (0., -1.), 'left': (1., 0.), 'right': (-1., 0.)}[direction]
        t = np.arange(n)/model.fps
        dist = np.where(t < speed/accel, .5*accel*t**2, .5*speed**2/accel+speed*(t-speed/accel))
        xz = torch.tensor(np.outer(dist, unit), dtype=torch.float32, device='cuda')
        heading = torch.tensor(np.tile([1., 0.], (n, 1)), dtype=torch.float32, device='cuda')
        return xz, heading

    for direction in args.directions:
        key, prompt = PROMPTS[direction]
        for seed in args.seeds:
            began = time.time()
            n = 50 if v == 'short' else 150 if v.startswith('history') else frames
            constraints, cfg = [], [2., 2.]
            if v.startswith('history'):
                seed_everything(seed)
                ref = model([prompt], [150], num_denoising_steps=steps, num_samples=1, post_processing=False)
                idx = torch.arange(100, device='cuda')
                constraints.append(FullBodyConstraintSet(model.skeleton, idx, ref['posed_joints'][0, :100],
                                                         ref['global_rot_mats'][0, :100]))
            if v in ('path-text', 'path-notext', 'history-path-notext'):
                if direction == 'turn':
                    continue                   # a turning path needs the heading's sign convention checked first
                first = 100 if v.startswith('history') else 0
                xz, heading = path(n-first, direction)
                if first:
                    xz = xz+constraints[0].smooth_root_2d[-1]
                constraints.append(Root2DConstraintSet(model.skeleton, torch.arange(first, n, device='cuda'), xz,
                                                       global_root_heading=heading if not first else None))
            if v in ('path-notext', 'history-path-notext'):
                cfg = [0., 2.]
            seed_everything(seed)
            if v == 'official':
                motion = model([prompt], [frames], num_denoising_steps=steps, num_samples=1, multi_prompt=True,
                               num_transition_frames=5, post_processing=False, return_numpy=True)  # as generate.py calls it
            else:
                motion = model([prompt], [n], num_denoising_steps=steps, num_samples=1, constraint_lst=constraints,
                               cfg_weight=cfg, post_processing=False, return_numpy=True)
            qpos = converter.dict_to_qpos(motion, root_quat_w_first=True)
            qpos = np.asarray(qpos)[0] if np.asarray(qpos).ndim == 3 else np.asarray(qpos)
            actions = qpos_to_actions(qpos, model.fps)
            start = 0 if v == 'short' else int(round(100*dw.RATE/model.fps)) if v.startswith('history') else int(dw.RATE)
            window = [start, len(actions)-1]
            seg = {'name': f'{v}-{direction}-s{seed}', 'direction': direction, 'window': window,
                   'source': {'pipeline': 'nv-tlabs/kimodo', 'model': name, 'prompt': prompt, 'seed': seed, 'variant': v,
                              'frames': n, 'diffusion_steps': steps, 'cfg_weight': cfg, 'post_processing': False},
                   'actions': actions.tolist()}
            (out/f"{seg['name']}.json").write_text(json.dumps(seg))
            a = actions[window[0]:]
            summary = dw.window_summary(actions, *window)
            g = dw.stepping(dw.reference_feet(a, fk))
            rows.append({'name': seg['name'], 'direction': direction, 'seed': seed, 'window': summary, 'gait': g,
                         'seconds_to_generate': time.time()-began})
            print(seg['name'], f"{summary['speed_m_s']:.2f} m/s, disp {np.round(summary['displacement_m'], 2).tolist()}, "
                  f"yaw {summary['yaw_deg']:.0f}, slide {g['slide_m_s'] or 0:.3f}, both {g['both_moving']:.2f}, "
                  f"step {g['step_length_m'] or 0:.2f}", flush=True)
    (out/'segments.json').write_text(json.dumps({'segments': rows}, indent=1))


if __name__ == '__main__':
    main()
